    /**
     * Min Samples
     *
     * 生效所需的最小样本数
     */
    min_samples?: number;
    /**
     * Active Instances
     *
     * 最近一次扫描到的活跃浏览器实例数
     */
    active_instances?: number;
    /**
     * Last Sample Mb
     *
     * 最近一次采样的单实例占用(MB)
     */
    last_sample_mb?: number | null;
    /**
     * Average Mb
     *
     * 窗口内单实例平均占用(MB)
     */
    average_mb?: number | null;
    /**
     * Peak Mb
     *
     * 单实例占用历史峰值(MB)
     */
    peak_mb?: number | null;
    /**
     * Reserved Mb
     *
     * 当前准入记账用的单实例预留额度(MB)
     */
    reserved_mb?: number;
    /**
     * Configured Reserved Mb
     *
     * 配置的基准预留额度(MB)
     */
