/**
 * WorkflowStepRequest
 *
 * 工作流步骤请求 - 与 WorkflowStep 模型对齐，与 BaseAction 创建参数对齐
 * 定义工作流中单个步骤的配置。
 */
export type WorkflowStepRequest = {
    /**
     * Action Id
     *
     * 操作ID：内置动作为名字符串(如 click/input/llm)，复合动作为雪花 int
     */
    action_id: number | string;
    /**
     * Action Type
     *
     * 操作类型
     */
    action_type?: BuiltinActionType | string | null;
    /**
     * Mid
     *
     * 用户ID
     */
    mid?: number | null;
    /**
     * Params
     *
     * 操作参数，支持 {{变量名}} 模板替换
     */
    params?: {
        [key: string]: unknown;
    };
    /**
     * Retry
     *
     * 失败重试次数
     */
    retry?: number;
    /**
     * 执行条件规则（结构化条件，不使用 eval）
     */
    condition?: ConditionRule | null;
    /**
     * Output Var
     *
     * 结果变量键名
     */
    output_var?: string | null;
    /**
     * Input Vars
     *
     * 输入变量
     */
    input_vars?: {
        [key: string]: unknown;
    };
    /**
     * Output Vars
     *
     * 输出变量名称列表
     */
    output_vars?: Array<string>;
    /**
     * Timeout
     *
     * 超时时间(毫秒)
     */
    timeout?: number;
    /**
     * Children
     *
     * 子步骤列表（用于循环体或分支）
     */
    children?: Array<WorkflowStepRequest> | null;
    /**
     * Loop Count
     *
     * 固定循环次数
     */
    loop_count?: number | null;
    /**
     * Loop While
     *
     * 条件循环，表达式为true时继续
     */
    loop_while?: string | null;
    /**
     * Loop Until
     *
     * 条件退出，表达式为true时退出
     */
    loop_until?: string | null;
};

